export interface Receipt { id: number; tenant: string; key: string; cents: number }
export class Ledger {
  readonly entries: Receipt[] = [];
  // Idempotency index: tenant -> key -> original receipt.
  private readonly receipts = new Map<string, Map<string, Receipt>>();
  // The body has no await, so the lookup and the debit run atomically; concurrent
  // calls with the same tenant/key cannot both debit.
  async apply(tenant: string, key: string, cents: number): Promise<Receipt> {
    let byKey = this.receipts.get(tenant);
    const existing = byKey?.get(key);
    if (existing) {
      if (existing.cents !== cents) throw new Error('key conflict');
      return existing;
    }
    const receipt = { id: this.entries.length + 1, tenant, key, cents };
    this.entries.push(receipt);
    if (!byKey) { byKey = new Map(); this.receipts.set(tenant, byKey); }
    byKey.set(key, receipt);
    return receipt;
  }
}

